import{_ as t,o as a,c as d,a3 as s}from"./chunks/framework.B8xISX-C.js";const f=JSON.parse('{"title":"specials","description":"","frontmatter":{},"headers":[],"relativePath":"reference/specials.md","filePath":"reference/specials.md"}'),i={name:"reference/specials.md"};function c(l,e,o,r,n,p){return a(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="specials" tabindex="-1">specials <a class="header-anchor" href="#specials" aria-label="Permalink to &quot;specials&quot;">​</a></h1><p>A ship special system, unlocked by an application (<code>app</code>). Several base specials have behaviour bound to their key in the combat rules.</p><p>A mod adds records in <code>records/specials/&lt;file&gt;.json</code> (<code>{ &quot;$schema&quot;: &quot;carina-records/1&quot;, &quot;catalog&quot;: &quot;specials&quot;, &quot;records&quot;: [...] }</code>) and changes base records with patch rows on catalog <code>specials</code>. Schema: <code>schemas/records/specials.schema.json</code>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>A mod record leaves out <code>id</code> and <code>prov</code>: the game assigns ids, and <code>prov</code> is the project&#39;s own provenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><span id="f-key" class="field-name"><code>key</code></span><a class="field-link" href="#f-key" aria-label="Link to key">#</a></td><td><code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: your package id with <code>-</code> read as <code>_</code>, then a name</td><td>yes</td><td></td></tr><tr><td><span id="f-app" class="field-name"><code>app</code></span><a class="field-link" href="#f-app" aria-label="Link to app">#</a></td><td>snake_case key</td><td>yes</td><td></td></tr><tr><td><span id="f-space" class="field-name"><code>space</code></span><a class="field-link" href="#f-space" aria-label="Link to space">#</a></td><td>[integer, integer, integer, integer, integer, integer]</td><td>yes</td><td></td></tr><tr><td><span id="f-cost" class="field-name"><code>cost</code></span><a class="field-link" href="#f-cost" aria-label="Link to cost">#</a></td><td>[integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0]</td><td>yes</td><td></td></tr><tr><td><span id="f-excludes" class="field-name"><code>excludes</code></span><a class="field-link" href="#f-excludes" aria-label="Link to excludes">#</a></td><td>list of snake_case key (no repeats)</td><td>yes</td><td></td></tr><tr><td><span id="f-indestructible" class="field-name"><code>indestructible</code></span><a class="field-link" href="#f-indestructible" aria-label="Link to indestructible">#</a></td><td>true or false</td><td>yes</td><td></td></tr><tr><td><span id="f-playerAvailable" class="field-name"><code>playerAvailable</code></span><a class="field-link" href="#f-playerAvailable" aria-label="Link to playerAvailable">#</a></td><td>true or false</td><td>yes</td><td></td></tr><tr><td><span id="f-strategic" class="field-name"><code>strategic</code></span><a class="field-link" href="#f-strategic" aria-label="Link to strategic">#</a></td><td>object (fields below) or null</td><td>yes</td><td></td></tr><tr><td><span id="f-strategic.type" class="field-name"><code>strategic.type</code></span><a class="field-link" href="#f-strategic.type" aria-label="Link to strategic.type">#</a></td><td>integer &gt;= 0</td><td>yes</td><td></td></tr><tr><td><span id="f-strategic.value" class="field-name"><code>strategic.value</code></span><a class="field-link" href="#f-strategic.value" aria-label="Link to strategic.value">#</a></td><td>integer &gt;= 0</td><td>yes</td><td></td></tr><tr><td><span id="f-nameKey" class="field-name"><code>nameKey</code></span><a class="field-link" href="#f-nameKey" aria-label="Link to nameKey">#</a></td><td>text key</td><td>yes</td><td></td></tr></tbody></table><h2 id="also-register-it-in" tabindex="-1">Also register it in <a class="header-anchor" href="#also-register-it-in" aria-label="Permalink to &quot;Also register it in&quot;">​</a></h2><ul><li>ship-design <code>auto.lists.&lt;class&gt;</code> lists, if the ship designer should fit it</li></ul><h2 id="computer-players" tabindex="-1">Computer players <a class="header-anchor" href="#computer-players" aria-label="Permalink to &quot;Computer players&quot;">​</a></h2><p>The ship designer fits specials from the <code>auto.lists</code> lists only; a new special with no list entry is never fitted by the AI.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>A special with new behaviour needs code; a new record can only carry the fields the shape has.</li><li>The design screens show <code>&lt;nameKey&gt;</code> with <code>.name</code> replaced by <code>.note</code>: the mod&#39;s English text needs it.</li></ul><h2 id="patch-paths" tabindex="-1">Patch paths <a class="header-anchor" href="#patch-paths" aria-label="Permalink to &quot;Patch paths&quot;">​</a></h2><p>Rows on this catalog address a record by <code>key</code> and a field by <code>path</code>:</p><ul><li><code>set</code>: <code>app</code>, <code>cost</code>, <code>excludes</code>, <code>indestructible</code>, <code>nameKey</code>, <code>playerAvailable</code>, <code>space</code>, <code>strategic</code>, <code>strategic.type</code>, <code>strategic.value</code></li><li><code>append</code>, <code>insertAfter</code>, <code>removeValue</code>: <code>excludes</code></li></ul>',15)])])}const u=t(i,[["render",c]]);export{f as __pageData,u as default};
